import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request.get("path") match {
            case Some(p: String) => p
            case _ => ""
        }
        let method = request.get("method") match {
            case Some(m: String) => m
            case _ => ""
        }

        if method == "OPTIONS" {
            return true
        }

        if is_start_with(path) {
            return true
        }

        let user = get_jwt_user(request)
        return user.isSome() match {
            case true => {
                set_current_user_info_and_log(user.get())
                true
            }
            case _ => false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        const prefixes = ["/api", "/login"]
        for (prefix in prefixes) {
            if request_uri.starts_with(prefix) {
                return true
            }
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request.get("headers") match {
            case Some(h: HashMap<String, Any>) => h
            case _ => return None
        }
        let auth = headers.get("Authorization") match {
            case Some(a: HashMap<String, Any>) => a
            case _ => return None
        }
        let user = auth.get("user") match {
            case Some(u: HashMap<String, Any>) => u
            case _ => return None
        }
        return Some(user)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name = user.get("name") match {
            case Some(n: String) => n
            case _ => ""
        }
        let address = user.get("address") match {
            case Some(a: String) => a
            case _ => "127.0.0.1"
        }
        let now = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
        println("[${now}] User ${name} accessed from ${address}")
    }
}

main(): Unit {
    let filter = AccessGatewayFilter()

    // Test OPTIONS method
    let optRequest = HashMap<String, Any>([
        ('method', 'OPTIONS'),
        ('path', '/api/data')
    ])
    println("OPTIONS request allowed: ${filter.filter(optRequest)}") // true

    // Test API path
    let apiRequest = HashMap<String, Any>([
        ('method', 'GET'),
        ('path', '/api/data')
    ])
    println("API request allowed: ${filter.filter(apiRequest)}") // true

    // Test login path
    let loginRequest = HashMap<String, Any>([
        ('method', 'POST'),
        ('path', '/login')
    ])
    println("Login request allowed: ${filter.filter(loginRequest)}") // true

    // Test valid JWT user
    let headers = HashMap<String, Any>([
        ('Authorization', HashMap<String, Any>([
            ('user', HashMap<String, Any>([
                ('name', 'user1'),
                ('address', '192.168.1.1')
            ])),
            ('jwt', 'user1' + DateTime.now().format("yyyy-MM-dd"))
        ]))
    ])
    let jwtRequest = HashMap<String, Any>([
        ('method', 'GET'),
        ('path', '/secure/data'),
        ('headers', headers)
    ])
    println("JWT secured request allowed: ${filter.filter(jwtRequest)}") // true

    // Test invalid request (no auth)
    let invalidRequest = HashMap<String, Any>([
        ('method', 'GET'),
        ('path', '/secure/data')
    ])
    println("Invalid request allowed: ${filter.filter(invalidRequest)}") // false
}

