import std.collection.HashMap
import std.convert.RadixConvertible

class BinaryDataProcessor {

    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var clean_str: String = ""
        for c in this.binary_string.chars() {
            if c == '0' || c == '1' {
                clean_str += c
            }
        }
        this.binary_string = clean_str
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        var info = HashMap<String, Float64>()
        var zero_count: Int64 = 0
        var one_count: Int64 = 0
        for c in this.binary_string.chars() {
            if c == '0' {
                zero_count += 1
            } else if c == '1' {
                one_count += 1
            }
        }
        var total_length = zero_count + one_count
        info["Zeroes"] = zero_count.toFloat64() / total_length.toFloat64()
        info["Ones"] = one_count.toFloat64() / total_length.toFloat64()
        info["Bit length"] = total_length.toFloat64()
        return info
    }

    public func convert_to_ascii(): String {
        var result: String = ""
        if this.binary_string.length() % 8 != 0 {
            return result
        }
        for i in 0..<this.binary_string.length() / 8 {
            var byte_str: String = this.binary_string.substring(i * 8, 8)
            if let byte = byte_str.toInt64(radix: 2) {
                result += byte.toChar()
            }
        }
        return result
    }

    public func convert_to_utf8(): String {
        return this.convert_to_ascii()
    }
}

