import std.collection.ArrayList

class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        for (i in (patLen - 1)..0 step -1) {
            if (pattern[i..=i] == char) {
                return i
            }
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        var i = patLen - 1
        var j = currentPos + i
        while (i >= 0 && j >= 0 && pattern[i..=i] == text[j..=j]) {
            i -= 1
            j -= 1
        }
        if (i == -1) {
            return -1
        }
        return j
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let result = ArrayList<Int64>()

        // Preprocess the bad character heuristic
        var badCharTable = Array<Int64>(repeating: -1, size: 256)
        for (i in 0..<patLen) {
            badCharTable[pattern[i].codePointAt(0) as Int64] = i
        }

        var s = 0
        while (s <= textLen - patLen) {
            var j = patLen - 1
            while (j >= 0 && pattern[j..=j] == text[(s + j)..=(s + j)]) {
                j -= 1
            }
            if (j < 0) {
                result.append(s)
                if (s + patLen < textLen) {
                    s += (patLen - badCharTable[text[s + patLen].codePointAt(0) as Int64])
                    if (s < 0) {
                        s = 0
                    }
                } else {
                    break
                }
            } else {
                let bc = badCharTable[text[s + j].codePointAt(0) as Int64]
                let shift = j - bc
                s += max(shift, 1)
            }
        }
        return result
    }
}

