import std.time.DateTime
import std.collection.ArrayList

class Event <: Equatable<Event> {

    let date: DateTime
    let start_time: DateTime
    let end_time: DateTime
    let description: String

    public init(date: DateTime, start_time: DateTime, end_time: DateTime, description: String) {
        this.date = date
        this.start_time = start_time
        this.end_time = end_time
        this.description = description
    }

    public override operator func != (that: Event): Bool {
        return this.date != that.date || this.start_time != that.start_time || 
               this.end_time != that.end_time || this.description != that.description
    }

    public override operator func == (that: Event): Bool {
        return this.date == that.date && this.start_time == that.start_time && 
               this.end_time == that.end_time && this.description == that.description
    }
}

class CalendarUtil {

    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        for (let i = 0; i < this.events.size; i++) {
            if (this.events[i] == event) {
                this.events.remove(i)
                return
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (let i = 0; i < this.events.size; i++) {
            if (this.events[i].date.equalsDate(date)) {
                result.add(this.events[i])
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (let i = 0; i < this.events.size; i++) {
            let event = this.events[i]
            if (start_time < event.end_time && end_time > event.start_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let result = ArrayList<(DateTime, DateTime)>()
        let sortedEvents = ArrayList<Event>(this.events)
        sortedEvents.sortWith((a: Event, b: Event) => a.start_time.compareTo(b.start_time))

        let startTime = date
        let endOfDay = date.addDays(1)

        for (let i = 0; i < sortedEvents.size; i++) {
            let event = sortedEvents[i]
            if (event.date.equalsDate(date)) {
                if (event.start_time > startTime) {
                    result.add((startTime, event.start_time))
                }
                startTime = event.end_time
            }
        }

        if (startTime < endOfDay) {
            result.add((startTime, endOfDay))
        }

        return result
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let result = ArrayList<Event>()
        let sortedEvents = ArrayList<Event>(this.events)
        sortedEvents.sortWith((a: Event, b: Event) => a.start_time.compareTo(b.start_time))

        let now = DateTime.now()
        for (let i = 0; i < sortedEvents.size && result.size < num_events; i++) {
            if (sortedEvents[i].start_time > now) {
                result.add(sortedEvents[i])
            }
        }
        return result
    }
}

