        let sortedEvents = ArrayList<Event>(this.events)
        sortedEvents.sortWith((a: Event, b: Event) => a.start_time.compareTo(b.start_time))

        let now = DateTime.now()
        for (let i = 0; i < sortedEvents.size && result.size < num_events; i++) {
            if (sortedEvents[i].start_time > now) {
                result.add(sortedEvents[i])
            }
