import std.time.DateTime

class Course <: Equatable<Course> {
    let name: String
    let start_time: String
    let end_time: String

    public init(name: String, start_time: String, end_time: String) {
        this.name = name
        this.start_time = start_time
        this.end_time = end_time
    }

    public override operator func != (that: Course): Bool {
        return this.name != that.name || this.start_time != that.start_time || this.end_time != that.end_time
    }

    public override operator func == (that: Course): Bool {
        return this.name == that.name && this.start_time == that.start_time && this.end_time == that.end_time
    }
}

class Classroom {
    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        if this.courses.contains(course) {
            return
        }
        if !this.check_course_conflict(new_course: course) {
            return
        }
        this.courses.add(course)
    }

    public func remove_course(course: Course): Unit {
        var index = -1
        for i in 0..<this.courses.size() {
            if this.courses[i] == course {
                index = i
                break
            }
        }
        if index != -1 {
            this.courses.remove(at: index)
        }
    }

    public func is_free_at(check_time: String): Bool {
        for course in this.courses {
            let start_dt = DateTime.parse(fmt: "yyyy/MM/dd HH:mm", str: course.start_time)
            let end_dt = DateTime.parse(fmt: "yyyy/MM/dd HH:mm", str: course.end_time)
            let check_dt = DateTime.parse(fmt: "yyyy/MM/dd HH:mm", str: check_time)
            if check_dt >= start_dt && check_dt < end_dt {
                return false
            }
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        let new_start = DateTime.parse(fmt: "yyyy/MM/dd HH:mm", str: new_course.start_time)
        let new_end = DateTime.parse(fmt: "yyyy/MM/dd HH:mm", str: new_course.end_time)
        for course in this.courses {
            let start = DateTime.parse(fmt: "yyyy/MM/dd HH:mm", str: course.start_time)
            let end = DateTime.parse(fmt: "yyyy/MM/dd HH:mm", str: course.end_time)
            if new_start < end && new_end > start {
                return false
            }
        }
        return true
    }
}

