import std.collection.ArrayList

class CombinationCalculator {

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m < 0 || m > n) {
            return 0
        }
        return factorial(n) / (factorial(m) * factorial(n - m))
    }

    public static func count_all(n: Int64): Int64 {
        let max = 9223372036854775807  // Int64.Max
        var sum = 0
        for (i in 1..n + 1) {
            let comb = count(n, i)
            if (sum > max - comb) {
                return max
            }
            sum += comb
        }
        return sum
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        this._select(0, ArrayList<String>(), 0, m, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for (i in 1..this.datas.size() + 1) {
            this._select(0, ArrayList<String>(), 0, i, result)
        }
        return result
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, m: Int64, result: ArrayList<ArrayList<String>>): Unit {
        if (resultIndex == m) {
            let newCombination = ArrayList<String>()
            for (i in 0..m) {
                newCombination.add(resultList.get(i))
            }
            result.add(newCombination)
            return
        }

        for (i in dataIndex..this.datas.size()) {
            resultList.set(resultIndex, this.datas.get(i))
            this._select(i + 1, resultList, resultIndex + 1, m, result)
        }
    }
}

