import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        var titles = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()
        var file = File(file_name)
        if !file.exists() {
            return (titles, data)
        }
        var reader = BufferedReader(FileReader(file))
        defer {
            reader.close()
        }
        var first_line = true
        while true {
            var line = reader.readLine()
            if line == null {
                break
            }
            var line_str = line!
            var strs = ArrayList<String>()
            var current = UnicodeStringExtension("")
            var in_quote = false
            var escape = false
            for c in line_str {
                if c == '"' && !escape {
                    in_quote = !in_quote
                } else if c == ',' && !in_quote {
                    strs.add(current.toString())
                    current = UnicodeStringExtension("")
                } else if c == '\\' && !escape {
                    escape = true
                } else {
                    if escape {
                        if c == 'n' {
                            current.append('\n')
                        } else if c == 't' {
                            current.append('\t')
                        } else if c == '\\' {
                            current.append('\\')
                        } else if c == '"' {
                            current.append('"')
                        } else {
                            current.append(c)
                        }
                        escape = false
                    } else {
                        current.append(c)
                    }
                }
            }
            strs.add(current.toString())
            if first_line {
                titles = strs
                first_line = false
            } else {
                data.add(strs)
            }
        }
        return (titles, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        var file = File(file_name)
        var writer = BufferedWriter(FileWriter(file))
        defer {
            writer.close()
        }
        for (i, row) in data.iterator() {
            for (j, str) in row.iterator() {
                if j > 0 {
                    writer.write(",")
                }
                var escaped = false
                for c in str {
                    if c == '"' || c == ',' || c == '\\' || c == '\n' || c == '\t' {
                        writer.write('"')
                        escaped = true
                        break
                    }
                }
                if escaped {
                    var s = str
                    s = s.replace("\\", "\\\\")
                    s = s.replace("\"", "\\\"")
                    s = s.replace("\n", "\\n")
                    s = s.replace("\t", "\\t")
                    writer.write(s)
                    writer.write('"')
                } else {
                    writer.write(str)
                }
            }
            if i < data.size() - 1 {
                writer.write("\n")
            }
        }
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        var new_file_name = save_file_name.substring(0, save_file_name.lastIndexOf(".")) + "_process.csv"
        var (titles, original_data) = this.read_csv(save_file_name)
        if original_data.size() == 0 || N < 0 || N >= titles.size() {
            return 0
        }
        var new_titles = ArrayList<String>()
        var new_data = ArrayList<ArrayList<String>>()
        new_titles.add(titles[N].capitalize())
        for row in original_data {
            if N < row.size() {
                var new_row = ArrayList<String>()
                new_row.add(row[N].capitalize())
                new_data.add(new_row)
            }
        }
        var processed_data = ArrayList<ArrayList<String>>()
        processed_data.add(new_titles)
        for row in new_data {
            processed_data.add(row)
        }
        var result = this.write_csv(processed_data, new_file_name)
        return result
    }
}
