import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        const n = data1.size()
        assert(n == data2.size(), "Data sizes must match")

        const sum1 = data1.fold(0.0, {acc, x => acc + x})
        const sum2 = data2.fold(0.0, {acc, x => acc + x})

        const mean1 = sum1 / n.toFloat64()
        const mean2 = sum2 / n.toFloat64()

        const var1 = data1.map({x => (x - mean1)**2}).sum()
        const var2 = data2.map({x => (x - mean2)**2}).sum()

        const cov = data1.fold(0.0, {acc, x, i => acc + (x - mean1) * (data2[i] - mean2)})

        const denom = sqrt(var1) * sqrt(var2)
        if (denom == 0.0) return 0.0
        return cov / denom
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        const n = data.size().toFloat64()
        const mean = data.sum() / n

        const adj_n = n / (n - 1.0) / (n - 2.0)
        const m3 = data.fold(0.0, {acc, x => acc + (x - mean)**3})
        const m2 = data.fold(0.0, {acc, x => acc + (x - mean)**2})

        if (m2 == 0.0) return 0.0
        return adj_n * m3 / (m2**1.5)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        const n = data.size().toFloat64()
        const mean = data.sum() / n

        const adj_n = (n - 1.0) * (n - 2.0) * (n - 3.0) / (n * (n + 1.0))
        const num = data.fold(0.0, {acc, x => acc + (x - mean)**4})
        const denom = data.fold(0.0, {acc, x => acc + (x - mean)**2})

        if (denom == 0.0) return 0.0
        return 3.0 + adj_n * (num / (denom**2)) - 3.0
    }

