    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'
        */
        let result = ArrayList<Byte>()
        for c in ciphertext {
            let char = c as Byte
            if char >= 'a' as Byte && char <= 'z' as Byte {
                let shifted = (char - 'a' as Byte - shift % 26 + 26) % 26 + 'a' as Byte
                result.append(shifted)
            } else if char >= 'A' as Byte && char <= 'Z' as Byte {
                let shifted = (char - 'A' as Byte - shift % 26 + 26) % 26 + 'A' as Byte
                result.append(shifted)
            } else {
                result.append(char)
            }
        }
        return String.fromBytes(result.toArray())
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl' (Note: Original docstring example might be incorrect, this implements proper Vigenere logic)
        */
        let result = ArrayList<Byte>()
        let keyBytes = ArrayList<Byte>()
        for k in this.key {
            let keyChar = k as Byte
            if keyChar >= 'a' as Byte && keyChar <= 'z' as Byte {
                keyBytes.append(keyChar - 'a' as Byte)
            } else if keyChar >= 'A' as Byte && keyChar <= 'Z' as Byte {
                keyBytes.append(keyChar - 'A' as Byte)
            }
        }
        let keyIndex = 0
        let keyLength = keyBytes.size()

        let i = 0
        for c in ciphertext {
            let char = c as Byte
            var shift = 0
            if keyLength > 0 {
                shift = keyBytes.get(keyIndex % keyLength) as Int64
            }
            if char >= 'a' as Byte && char <= 'z' as Byte {
                let shifted = (char - 'a' as Byte - shift + 26) % 26 + 'a' as Byte
                result.append(shifted)
            } else if char >= 'A' as Byte && char <= 'Z' as Byte {
                let shifted = (char - 'A' as Byte - shift + 26) % 26 + 'A' as Byte
                result.append(shifted)
            } else {
                result.append(char)
            }
        }
        return String.fromBytes(result.toArray())
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'
        */
        if rails <= 1 {
            return encrypted_text
        }
        let length = encrypted_text.length()
        let railPositions = ArrayList<ArrayList<Int64>>()
        for _ in 0..rails {
            railPositions.append(ArrayList<Int64>())
        }
        let rail = 0
        let direction = 1
        for i in 0..length {
            railPositions.get(rail).append(i as Int64)
            rail += direction
            if rail == 0 || rail == rails - 1 {
                direction = -direction
            }
        }
        let charIndices = ArrayList<Int64>()
        for rail in 0..rails {
            for index in railPositions.get(rail) {
                charIndices.append(index)
            }
        }
        let result = ArrayList<Byte>(length)
        for _ in 0..length {
            result.append(0)
        }
        let encryptedBytes = encrypted_text.toBytes()
        let j = 0
        for i in charIndices {
            if j < encryptedBytes.size() {
                result.set(i as Int32, encryptedBytes.get(j))
                j += 1
            }
        }
        return String.fromBytes(result.toArray())
    }
}

