import std.collection.ArrayList
import std.collection.Queue
import std.sort.*

class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i: Int64 in 0..<3) {
            for (j: Int64 in 0..<3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        var new_state = ArrayList<ArrayList<Int64>>()
        for (row in state) {
            new_state.add(ArrayList<Int64>(row))
        }

        let (i, j) = this.find_blank(state: state)
        if (direction == "up" && i > 0) {
            new_state[i][j] = new_state[i-1][j]
            new_state[i-1][j] = 0
        } else if (direction == "down" && i < 2) {
            new_state[i][j] = new_state[i+1][j]
            new_state[i+1][j] = 0
        } else if (direction == "left" && j > 0) {
            new_state[i][j] = new_state[i][j-1]
            new_state[i][j-1] = 0
        } else if (direction == "right" && j < 2) {
            new_state[i][j] = new_state[i][j+1]
            new_state[i][j+1] = 0
        }
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = this.find_blank(state: state)

        if (i > 0) {
            moves.add("up")
        }
        if (i < 2) {
            moves.add("down")
        }
        if (j > 0) {
            moves.add("left")
        }
        if (j < 2) {
            moves.add("right")
        }
        return moves
    }

    public func solve(): ArrayList<String> {
        class StateWithPath {
            var state: ArrayList<ArrayList<Int64>>
            var path: ArrayList<String>

            public init(state: ArrayList<ArrayList<Int64>>, path: ArrayList<String>) {
                this.state = state
                this.path = path
            }
        }

        let queue = Queue<StateWithPath>()
        let visited = ArrayList<ArrayList<ArrayList<Int64>>>()

        queue.enqueue(StateWithPath(state: this.initial_state, path: ArrayList<String>()))

        while (!queue.isEmpty()) {
            let current = queue.dequeue()

            if (isEqual(current.state, this.goal_state)) {
                return current.path
            }

            let has_visited = visited |> any<ArrayList<ArrayList<Int64>>>({ state: ArrayList<ArrayList<Int64>> => isEqual(state, current.state) })
            if (has_visited) {
                continue
            }
            visited.add(current.state)

            let possible_moves = this.get_possible_moves(state: current.state)
            for (direction in possible_moves) {
                let new_state = this.move(state: current.state, direction: direction)
                let new_path = ArrayList<String>(current.path)
                new_path.add(direction)
                queue.enqueue(StateWithPath(state: new_state, path: new_path))
            }
        }

        return ArrayList<String>()
    }

    private func isEqual(a: ArrayList<ArrayList<Int64>>, b: ArrayList<ArrayList<Int64>>): Bool {
        for (i: Int64 in 0..<3) {
            for (j: Int64 in 0..<3) {
                if (a[i][j] != b[i][j]) {
                    return false
                }
            }
        }
        return true
    }
}

func any<T>(data: ArrayList<T>, predicate: (T) -> Bool): Bool {
    for (item in data) {
        if (predicate(item)) {
            return true
        }
    }
    return false
}

