class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'
        */
        var result = StringBuilder()
        for i in 0..<plaintext.size {
            var char = plaintext[i as Int64] as Rune
            if char.isLetter() {
                var base = if char.isLower() { 'a' } else { 'A' } as Rune
                char = ((char - base + shift) % 26 + base) as Rune
            }
            result.append(char)
        }
        return result.toString()
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'
        */
        var result = StringBuilder()
        var keyIndex = 0 as Int64
        for i in 0..<plain_text.size {
            var char = plain_text[i as Int64] as Rune
            if char.isLetter() {
                var keyChar = this.key[keyIndex % this.key.size as Rune] as Rune
                keyChar = if keyChar.isLower() { keyChar - 'a' } else { keyChar - 'A' } as Rune
                var base = if char.isLower() { 'a' } else { 'A' } as Rune
                char = ((char - base + keyChar) % 26 + base) as Rune
                keyIndex += 1
            }
            result.append(char)
        }
        return result.toString()
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'
        */
        if rails <= 1 {
            return plain_text
        }
        var railFence = ArrayList<StringBuilder>()
        for _ in 0..<rails {
            railFence.add(StringBuilder())
        }
        var currentRail = 0 as Int64
        var direction = 1 as Int64
        for i in 0..<plain_text.size {
            var char = plain_text[i as Int64] as Rune
            railFence[currentRail].append(char)
            currentRail += direction
            if currentRail == 0 || currentRail == rails - 1 {
                direction = -direction
            }
        }
        var result = StringBuilder()
        for i in 0..<railFence.size {
            result.append(railFence[i].toString())
        }
        return result.toString()
    }
}

