import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(expression: expression)
        let stack = ArrayList<Decimal>()
        for (token in postfix_stack) {
            if (!ExpressionCalculator.is_operator(token)) {
                stack.add(Decimal.valueOf(token))
            } else {
                let second_value = stack.removeLast()
                let first_value = stack.removeLast()
                let result = ExpressionCalculator._calculate(
                    first_value: first_value,
                    second_value: second_value,
                    current_op: token
                )
                stack.add(result)
            }
        }
        return stack.last().toFloat64()
    }

    public func prepare(expression: String): Unit {
        let transformed = ExpressionCalculator.transform(expression: expression)
        let tokens = transformed.split("(?<=[-+*/%()])|(?=[-+*/%()])")
        let operator_stack = ArrayList<String>()
        postfix_stack.clear()

        for (token in tokens) {
            if (token == "") {
                continue
            }
            if (token == "(") {
                operator_stack.add(token)
            } else if (token == ")") {
                while (!operator_stack.isEmpty() && operator_stack.last() != "(") {
                    postfix_stack.add(operator_stack.removeLast())
                }
                operator_stack.removeLast() // Remove '('
            } else if (ExpressionCalculator.is_operator(token)) {
                while (!operator_stack.isEmpty() && 
                       operator_stack.last() != "(" && 
                       compare(operator_stack.last(), token)) {
                    postfix_stack.add(operator_stack.removeLast())
                }
                operator_stack.add(token)
            } else {
                postfix_stack.add(token)
            }
        }

        while (!operator_stack.isEmpty()) {
            postfix_stack.add(operator_stack.removeLast())
        }
    }

    public static func is_operator(c: String): Bool {
        switch (c) {
            case "+", "-", "*", "/", "%", "(", ")" => true
            default => false
        }
    }

    public func compare(cur: String, peek: String): Bool {
        let op_map: Map<String, Int64> = {
            "+": 4, 
            "-": 4, 
            "*": 3, 
            "/": 3, 
            "%": 3, 
            "(": 0,
            ")": -1
        }
        let cur_idx = op_map[cur] ?? -1
        let peek_idx = op_map[peek] ?? -1
        return !(peek == "(") && cur_idx <= peek_idx
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        switch (current_op) {
            case "+" => return first_value + second_value
            case "-" => return first_value - second_value
            case "*" => return first_value * second_value
            case "/" => 
                if (second_value == 0) {
                    throw IllegalArgumentException("Division by zero")
                }
                return first_value / second_value
            case "%" => return first_value % second_value
            defalut => throw IllegalArgumentException("Invalid operator")
        }
    }

    public static func transform(expression: String): String {
        let regex = Regex("\\s+")
        return regex.replaceAll(expression, "")
    }
}

