import std.math.abs

class FitnessTracker {

    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("male", ArrayList<Int64>([20, 25]))]))
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("female", ArrayList<Int64>([19, 24]))]))
    }

    public func get_BMI(): Float64 {
        return this.weight / (this.height ** 2)
    }

    public func condition_judge(): Int64 {
        let bmi = this.get_BMI()
        var std: ArrayList<Int64> = ArrayList<Int64>()
        var found = false
        for map in this.BMI_std {
            for (key, range) in map {
                if key == this.sex {
                    std = range
                    found = true
                    break
                }
            }
            if found {
                break
            }
        }
        if std.size() != 2 {
            return 0
        }
        let low = std[0].toFloat64()
        let high = std[1].toFloat64()
        if bmi < low {
            return -1
        } else if bmi > high {
            return 1
        } else {
            return 0
        }
    }

    public func calculate_calorie_intake(): Float64 {
        var bmr: Float64 = 0.0
        if this.sex == "male" {
            bmr = 10.0 * this.weight + 6.25 * this.height - 5.0 * this.age.toFloat64() + 5.0
        } else if this.sex == "female" {
            bmr = 10.0 * this.weight + 6.25 * this.height - 5.0 * this.age.toFloat64() - 161.0
        } else {
            return 0.0
        }
        let condition = this.condition_judge()
        if condition == 1 {
            return bmr * 1.2
        } else if condition == -1 {
            return bmr * 1.6
        } else {
            return bmr * 1.4
        }
    }
}

main() {
    let fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
    println(fitnessTracker.get_BMI())
    println(fitnessTracker.condition_judge())
    println(fitnessTracker.calculate_calorie_intake())

    let fitnessTracker2 = FitnessTracker(1.6, 50.0, 25, "female")
    println(fitnessTracker2.get_BMI())
    println(fitnessTracker2.condition_judge())
    println(fitnessTracker2.calculate_calorie_intake())
    return 0
}

