import std.collection.ArrayList

class GomokuGame {

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if row < 0 || row >= board_size || col < 0 || col >= board_size || board[row][col] != " " {
            return false
        }
        board[row][col] = current_player
        current_player = if current_player == "X" { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        for (i in 0..board_size) {
            for (j in 0..board_size) {
                if board[i][j] != " " {
                    let directions = [(1, 0), (0, 1), (1, 1), (1, -1)] // horizontal, vertical, two diagonals
                    for ((dx, dy) in directions) {
                        if _check_five_in_a_row(i, j, (dx, dy)) {
                            return Option(board[i][j])
                        }
                    }
                }
            }
        }
        return Option.None<String>()
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dx, dy) = direction
        let player = board[row][col]
        let directions = [(1, 0), (-1, 0), (0, 1), (0, -1)] // 4 directions to check around the starting point
        for (d in directions) {
            var count = 1
            // Search in positive direction
            for (k in 1..5) {
                let new_row = row + k * dx
                let new_col = col + k * dy
                if new_row < 0 || new_row >= board_size || new_col < 0 || new_col >= board_size || board[new_row][new_col] != player {
                    break
                }
                count += 1
            }
            // Search in negative direction (only needed if dx or dy is non-zero, but kept for completeness)
            for (k in 1..5) {
                let new_row = row - k * dx
                let new_col = col - k * dy
                if new_row < 0 || new_row >= board_size || new_col < 0 || new_col >= board_size || board[new_row][new_col] != player {
                    break
                }
                count += 1
            }
            if count >= 5 {
                return true
            }
        }
        return false
    }
}

