import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for i in 0..<x_interp.size() {
            let xi = x_interp[i]
            if xi <= x[0] {
                result.add(y[0])
                continue
            }
            if xi >= x[x.size()-1] {
                result.add(y[y.size()-1])
                continue
            }
            var j = 0
            while j < x.size()-1 && x[j+1] < xi {
                j += 1
            }
            let x0 = x[j]
            let x1 = x[j+1]
            let y0 = y[j]
            let y1 = y[j+1]
            let interp_y = y0 + (y1 - y0) * (xi - x0) / (x1 - x0)
            result.add(interp_y)
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for xi in x_interp {
            for yi in y_interp {
                var j = 0
                while j < x.size()-1 && x[j+1] < xi {
                    j += 1
                }
                var k = 0
                while k < y.size()-1 && y[k+1] < yi {
                    k += 1
                }

                let x0 = x[j]
                let x1 = x[j+1]
                let y0 = y[k]
                let y1 = y[k+1]

                // Bilinear interpolation
                let z00 = z[j][k]
                let z01 = z[j][k+1]
                let z10 = z[j+1][k]
                let z11 = z[j+1][k+1]

                let interp_z = 
                    z00 * (x1 - xi) * (y1 - yi) +
                    z10 * (xi - x0) * (y1 - yi) +
                    z01 * (x1 - xi) * (yi - y0) +
                    z11 * (xi - x0) * (yi - y0) / 
                    ((x1 - x0) * (y1 - y0))
                result.add(interp_z)
            }
        }

        // Flatten result (assuming y_interp is processed first in nested loops)
        // Re-implement with separate loops for clarity
        let flatResult = ArrayList<Float64>()
        outerLoop:
        for xi in x_interp {
            // Find x segment
            var j = 0
            while j < x.size()-1 && x[j+1] < xi {
                j += 1
            }
            if j >= x.size()-1 {
                j = x.size()-2
            }

            let x0 = x[j]
            let x1 = x[j+1]

            // For each yi in y_interp
            for yi in y_interp {
                // Find y segment
                var k = 0
                while k < y.size()-1 && y[k+1] < yi {
