import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // Validate input
        if testData.size() == 0 || testData.get(0).size() != k {
            return 0.0
        }

        let n = testData.get(0).size()
        var observedAgreement: Float64 = 0.0
        var chanceAgreement: Float64 = 0.0
        var rowSums = ArrayList<Float64>()

        // Calculate row sums and observed agreement
        for (i in 0..<testData.size()) {
            if testData.get(i).size() != n {
                return 0.0
            }

            var sum: Float64 = 0.0
            for (j in 0..<n) {
                sum += Float64(testData.get(i).get(j))
            }
            rowSums.add(sum)

            if sum == 0 {
                continue  // Avoid division by zero
            }

            var maxCount: Float64 = 0.0
            var maxIndex = 0
            for (j in 0..<n) {
                let count = Float64(testData.get(i).get(j))
                if count > maxCount {
                    maxCount = count
                    maxIndex = j
                }
            }

            let prob = maxCount / sum
            observedAgreement += maxCount
            chanceAgreement += sum * prob * prob
        }

        if rowSums.size() == 0 {
            return 0.0
        }

        let total = rowSums.stream().reduce(0.0, {x, y => x + y})
        observedAgreement = observedAgreement / total
        chanceAgreement = chanceAgreement / total

        return (observedAgreement - chanceAgreement) / (1.0 - chanceAgreement)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        if (N == 0 || k == 0 || testData.size() != N) {
            return 0.0
        }

        // Calculate sum of all ratings
        var sumRatings: Int64 = 0
        for (i in 0..<N) {
            if (testData.get(i).size() != k) {
                return 0.0
            }
            for (j in 0..<k) {
                sumRatings += testData.get(i).get(j)
            }
        }

        // Calculate overall agreement proportion (P0)
        let P0: Float64 = Float64(sumRatings) / Float64(N * n)

        // Calculate category proportions (Pi)
        var categorySums = ArrayList<Int64>()
        for (j in 0..<k) {
            var sum: Int64 = 0
            for (i in 0..<N) {
                sum += testData.get(i).get(j)
            }
            categorySums.add(sum)
        }

        var Pi = ArrayList<Float64>()
        for (j in 0..<k) {
            Pi.add(Float64(categorySums.get(j)) / Float64(N * n))
        }

        // Calculate expected agreement by chance (Pe)
        var Pe: Float64 = 0.0
        for (j in 0..<k) {
            let pi = Pi.get(j)
            Pe += pi * pi
        }

        // Calculate kappa
        var P = 0.0
        for (i in 0..<N) {
            var NiJSum: Float64 = 0.0
            var NiSum: Float64 = 0.0
            for (j in 0..<k) {
                let niJ = testData.get(i).get(j)
                NiJSum += niJ * niJ
                NiSum += niJ
            }
            if (NiSum > 0) {
                P += (NiJSum - NiSum) / (NiSum * (n - 1))
            }
        }
        P = P / Float64(N)

        if (1.0 - Pe == 0.0) {
            return 0.0
        }
        return (P - Pe) / (1.0 - Pe)
    }
}

