            let row = ArrayList<String>()
            for (j in 0..<cols) {
                let index = (Int64)(random.nextInt64() % iconCount)
                row.add(ICONS[(Int64)(index)])
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        // Check if positions are within bounds
        if (x1 < 0 || x1 >= rows || y1 < 0 || y1 >= cols || 
            x2 < 0 || x2 >= rows || y2 < 0 || y2 >= cols) {
            return false
        }

        // Check if positions are the same
        if (x1 == x2 && y1 == y2) {
            return false
        }

        // Check if icons are the same
        if (board[(Int64)(x1)][(Int64)(y1)] != board[(Int64)(x2)][(Int64)(y2)]) {
            return false
        }

        // Check if there's a valid path
        return has_path(pos1: pos1, pos2: pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let visited = ArrayList<(Int64, Int64)>()
        return check_path(pos1: pos1, pos2: pos2, visited: visited)
    }

    private func check_path(pos1: (Int64, Int64), pos2: (Int64, Int64), visited: ArrayList<(Int64, Int64)>): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        if (pos1 == pos2) {
            return true
        }

        if (contains(visited: visited, pos: pos1)) {
            return false
        }
        visited.add(pos1)

        let directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        let currentIcon = board[(Int64)(x1)][(Int64)(y1)]

        for (dx, dy) in directions {
            let nx = x1 + (Int64)(dx)
            let ny = y1 + (Int64)(dy)
            let newPos = (nx, ny)

            // Check if adjacent position is within bounds and empty or same icon
            if (nx >= 0 && nx < BOARD_SIZE[0] && ny >= 0 && ny < BOARD_SIZE[1]) {
                // If empty (for pathfinding), we can move through empty spaces between icons
                // This is a simplified version, actual game would have stricter rules
                if (board[(Int64)(nx)][(Int64)(ny)] == " " || 
                    board[(Int64)(nx)][(Int64)(ny)] == board[(Int64)(x2)][(Int64)(y2)]) {
                    if (check_path(pos1: newPos, pos2: pos2, visited: visited)) {
                        return true
                    }
                }
            }
        }

        // Special case: direct line of sight (L-shape turns allowed)
        // This is simplified, actual implementation would need more complex pathfinding
        if ((x1 == x2 || y1 == y2) && !visited.any(${ board[$0.0][$0.1] != " " && board[$0.0][$0.1] != currentIcon })) {
            // Check straight line
            let stepX = if (x1 == x2) 0 else (if (x1 < x2) 1 else -1)
            let stepY = if (y1 == y2) 0 else (if (y1 < y2) 1 else -1)

            var nx = x1 + stepX
            var ny = y1 + stepY
            var blocked = false

            while (nx != x2 || ny != y2) {
                if (nx < 0 || nx >= BOARD_SIZE[0] || ny < 0 || ny >= BOARD_SIZE[1]) {
                    blocked = true
                    break
                }
                if (board[(Int64)(nx)][(Int64)(ny)] != " ") {
                    blocked = true
                    break
                }
                nx += stepX
                ny += stepY
            }

            if (!blocked) {
                return true
            }
        }

        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board[(Int64)(x1)][(Int64)(y1)] = " "
        board[(Int64)(x2)][(Int64)(y2)] = " "

        // Optional: fill empty spaces with new icons (not in requirements)
    }

    public func is_game_over(): Bool {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        for (i in 0..<rows) {
            for (j in 0..<cols) {
                if (board[(Int64)(i)][(Int64)(j)] != " ") {
                    return false
                }
            }
        }
        return true
    }
}
