import std.collection.ArrayList
import std.math.abs
import std.sort.*

class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        if data is (ArrayList<Int64>, Int64) {
            let (array, groundTruthNum) = data as! (ArrayList<Int64>, Int64)
            let recipRank = computeReciprocalRank(array: array, groundTruthNum: groundTruthNum)
            return (recipRank, ArrayList<Float64>([recipRank]))
        } else if data is ArrayList<(ArrayList<Int64>, Int64)> {
            let dataList = data as! ArrayList<(ArrayList<Int64>, Int64)>
            var recipRanks = ArrayList<Float64>()
            var totalRecipRank: Float64 = 0
            for (array, groundTruthNum) in dataList {
                let recipRank = computeReciprocalRank(array: array, groundTruthNum: groundTruthNum)
                recipRanks.add(recipRank)
                totalRecipRank += recipRank
            }
            let avgRecipRank = totalRecipRank / Float64(dataList.size())
            return (avgRecipRank, recipRanks)
        } else {
            throw IllegalArgumentException("Invalid data format")
        }
    }

    private static func computeReciprocalRank(array: ArrayList<Int64>, groundTruthNum: Int64): Float64 {
        for (i, num) in array.enumerate() {
            if num == 1 {
                return 1.0 / Float64(i + 1)
            }
        }
        return 0.0
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        if data is (ArrayList<Int64>, Int64) {
            let (array, groundTruthNum) = data as! (ArrayList<Int64>, Int64)
            let ap = computeAveragePrecision(array: array, groundTruthNum: groundTruthNum)
            return (ap, ArrayList<Float64>([ap]))
        } else if data is ArrayList<(ArrayList<Int64>, Int64)> {
            let dataList = data as! ArrayList<(ArrayList<Int64>, Int64)>
            var aps = ArrayList<Float64>()
            var totalAP: Float64 = 0
            for (array, groundTruthNum) in dataList {
                let ap = computeAveragePrecision(array: array, groundTruthNum: groundTruthNum)
                aps.add(ap)
                totalAP += ap
            }
            let avgAP = totalAP / Float64(dataList.size())
            return (avgAP, aps)
        } else {
            throw IllegalArgumentException("Invalid data format")
        }
    }

    private static func computeAveragePrecision(array: ArrayList<Int64>, groundTruthNum: Int64): Float64 {
        var truePositives = 0
        var precisionSum: Float64 = 0
        var truePositivesAtRankK = 0

        for (rank, num) in array.enumerate() {
            if num == 1 {
                truePositives += 1
                // Calculate precision at rank k (0-based)
                let currentPrecision = Float64(truePositives) / Float64(rank + 1)
                if truePositives == 1 {
                    precisionSum += currentPrecision
                } else {
                    // For AP, we consider the maximum precision at each new relevant doc found
                    // So we store all precision values at the ranks where relevant docs are found
                    // Here we simplify by using the precision at each rank (susceptible to error)
                    // For accurate AP calculation, we should track max precision at each relevant doc position
                    let maxPrecision = currentPrecision
                    precisionSum += maxPrecision
                }
            }
        }

        // More accurate AP calculation should consider only the ranks where relevant docs appear
        // Here is a corrected version:
        var accuratePrecisionSum: Float64 = 0
        var relevantCount = 0
        var relevantRanks = ArrayList<Int64>()

        // First collect all ranks where relevant docs appear
        for (rank, num) in array.enumerate() {
            if num == 1 {
                relevantCount += 1
                relevantRanks.add(Int64(rank))
            }
        }

        // Calculate precision at each relevant doc position
        var cumulativeTruePositives = 0
        for (i, relevantRank) in relevantRanks.enumerate() {
            let truePositivesUpToThis = i + 1
            let totalDocsUpToThis = Int64(relevantRank) + 1
            let precisionAtThis = Float64(truePositivesUpToThis) / Float64(totalDocsUpToThis)
            accuratePrecisionSum += precisionAtThis
        }

        if relevantCount == 0 {
            return 0.0
        }

        return accuratePrecisionSum / Float64(relevantCount)
    }
