                } else {
                    // For AP, we consider the maximum precision at each new relevant doc found
                    // So we store all precision values at the ranks where relevant docs are found
                    // Here we simplify by using the precision at each rank (susceptible to error)
                    // For accurate AP calculation, we should track max precision at each relevant doc position
                    let maxPrecision = currentPrecision
                    precisionSum += maxPrecision
                }
            }
        }

        // More accurate AP calculation should consider only the ranks where relevant docs appear
        // Here is a corrected version:
        var accuratePrecisionSum: Float64 = 0
        var relevantCount = 0
        var relevantRanks = ArrayList<Int64>()

        // First collect all ranks where relevant docs appear
        for (rank, num) in array.enumerate() {
