                relevantRanks.add(Int64(rank))
            }
        }

        // Calculate precision at each relevant doc position
        var cumulativeTruePositives = 0
        for (i, relevantRank) in relevantRanks.enumerate() {
            let truePositivesUpToThis = i + 1
            let totalDocsUpToThis = Int64(relevantRank) + 1
            let precisionAtThis = Float64(truePositivesUpToThis) / Float64(totalDocsUpToThis)
            accuratePrecisionSum += precisionAtThis
        }

        if relevantCount == 0 {
            return 0.0
        }

        return accuratePrecisionSum / Float64(relevantCount)
    }
}
