import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        var seats = ArrayList<ArrayList<Int64>>()
        for _ in 0..<n {
            var row = ArrayList<Int64>()
            for _ in 0..<n {
                row.add(0)
            }
            seats.add(row)
        }
        let movie = HashMap<String, Any>()
        movie.put("name", name)
        movie.put("price", price)
        movie.put("start_time", start)
        movie.put("end_time", end)
        movie.put("seats", seats)
        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for movie in movies {
            let movie_name = movie.get("name").getOrThrow() as String
            if movie_name == name {
                let seats = movie.get("seats").getOrThrow() as ArrayList<ArrayList<Int64>>
                for seat in seats_to_book {
                    let row = seat[0] as Int64
                    let col = seat[1] as Int64
                    if row < 0 || row >= seats.size() || col < 0 || col >= seats[0].size() {
                        return "Booking failed."
                    }
                    if seats[row as Int64][col as Int64] == 1 {
                        return "Booking failed."
                    }
                }
                for seat in seats_to_book {
                    let row = seat[0] as Int64
                    let col = seat[1] as Int64
                    seats[row as Int64][col as Int64] = 1
                }
                return "Booking success."
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        var available = ArrayList<String>()
        for movie in movies {
            let movie_start = movie.get("start_time").getOrThrow() as DateTime
            let movie_end = movie.get("end_time").getOrThrow() as DateTime
            if (movie_start >= start && movie_start <= end) || (movie_end >= start && movie_end <= end) || (movie_start <= start && movie_end >= end) {
                let all_seats_available = true
                let seats = movie.get("seats").getOrThrow() as ArrayList<ArrayList<Int64>>
                for row in seats {
                    for col in row {
                        if col == 1 {
                            all_seats_available = false
                            break
                        }
                    }
                    if !all_seats_available {
                        break
                    }
                }
                if all_seats_available {
                    let movie_name = movie.get("name").getOrThrow() as String
                    available.add(movie_name)
                }
            }
        }
        return available
    }
}

