import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var words_list = ArrayList<ArrayList<String>>()
        let word_pattern = Regex(r"\b[\w']+\b") // Simple word matching pattern (includes apostrophes in words)
        let replace_non_letters = Regex("[^a-zA-Z\\s']") // Keep only letters, spaces and apostrophes

        for (s in string_list) {
            // Keep only English letters, spaces and apostrophes
            var cleaned = replace_non_letters.replaceAll(s.toLowerCase(), "")
            // Find all words using regex
            var words = ArrayList<String>()
            for (md in word_pattern.findAll(cleaned)) {
                words.add(md.matchString())
            }
            words_list.add(words)
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var frequency = HashMap<String, Int64>()

        for (words in words_list) {
            for (word in words) {
                let count = frequency.getOrDefault(word, 0)
                frequency.put(word, count + 1)
            }
        }

        // Convert to list for sorting
        var entries = ArrayList<(String, Int64)>()
        for ((word, count) in frequency) {
            entries.add((word, count))
        }

        // Sort by frequency descending, then by word ascending
        sort(entries, by: { l, r => 
            if (l.2 != r.2) {
                r.2.compare(l.2) // Higher frequency first
            } else {
                l.1.compare(r.1) // Then alphabetical
            }
        })

        // Return as HashMap (will lose order, but top 5 will be first in entries)
        var result = HashMap<String, Int64>()
        var i: Int64 = 0
        for (entry in entries) {
            if (i >= 5) break
            result.put(entry.1, entry.2)
            i += 1
        }

        return result
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = this.process_data(string_list)
        return this.calculate_word_frequency(words_list)
    }
}

