import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {

    public static func decimal_to_binary(decimal_num: Int64): String {
        return RadixConvertible.toString(decimal_num, radix: 2)
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        if !Parsable.isParsable(binary_num, radix: 2) {
            throw IllegalArgumentException("Invalid binary string")
        }
        return Parsable.parseInt64(binary_num, radix: 2)
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        return RadixConvertible.toString(decimal_num, radix: 8)
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        if !Parsable.isParsable(octal_num, radix: 8) {
            throw IllegalArgumentException("Invalid octal string")
        }
        return Parsable.parseInt64(octal_num, radix: 8)
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        return RadixConvertible.toString(decimal_num, radix: 16, uppercase: false)
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        if !Parsable.isParsable(hex_num, radix: 16) {
            throw IllegalArgumentException("Invalid hex string")
        }
        return Parsable.parseInt64(hex_num, radix: 16)
    }
}

