import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        if x == null {
            return ""
        }
        return this.format_string(x!.toString())
    }

    public func format_string(x: String): String {
        var parts: Array<String> = []
        var integerPart: String = ""
        var decimalPart: String = ""
        let pointIdx = x.indexOf(".")
        if pointIdx == -1 {
            integerPart = x
        } else {
            integerPart = x.substring(0, pointIdx)
            decimalPart = x.substring(pointIdx + 1)
        }
        integerPart = this.pad_zeros(integerPart, 3)
        let splitCount = integerPart.length() / 3
        for i in 0..<splitCount {
            let start = i * 3
            let end = start + 3
            let part = integerPart.substring(start, end)
            if !part.trim().equals("000") {
                parts.push(this.trans_three(part) + " " + this.parse_more(splitCount - 1 - i))
            }
        }
        parts.reverse()
        var result: String = parts.filter{ s => !s.equals("") }.join(" ")
        if decimalPart.length() > 0 {
            decimalPart = decimalPart.padEnd(3, '0')
            var decimalWords: Array<String> = []
            for i in 0..<3 {
                let num = decimalPart.charAt(i).toString().toInt()!
                if num > 0 {
                    decimalWords.push(this.NUMBER[num])
                }
            }
            if decimalWords.length() > 0 {
                result += " POINT " + decimalWords.join(" ")
            }
        }
        if result.isEmpty() {
            result = "ZERO"
        } else {
            result += " ONLY"
        }
        return result
    }

    public func trans_two(s: String): String {
        let n1: Int64 = s.substring(0, 1).toInt()!
        let n2: Int64 = s.substring(1, 2).toInt()!
        if n1 == 1 {
            return this.NUMBER_TEEN[n2.toInt()!]
        } else if n1 == 0 {
            return this.NUMBER[n2.toInt()!]
        } else {
            var rest: String = ""
            if n2 > 0 {
                rest = "-" + this.NUMBER[n2.toInt()!]
            }
            return this.NUMBER_TEN[n1.toInt()! - 1] + rest
        }
    }

    public func trans_three(s: String): String {
        var result: String = ""
        let h = s.substring(0, 1).toInt()!
        let t = s.substring(1, 2).toInt()!
        let u = s.substring(2, 3).toInt()!
        if h > 0 {
            result += this.NUMBER[h] + " HUNDRED"
            if t > 0 || u > 0 {
                result += " AND "
            }
        }
        let twoPart = t.toString() + u.toString()
        if twoPart.equals("00") {
            return result
        }
        return result + this.trans_two(twoPart)
    }

    public func parse_more(i: Int64): String {
        return this.NUMBER_MORE[i.toInt()! + 1]
    }

    private func pad_zeros(numStr: String, digit: Int64): String {
        var numStr = numStr
        let diff = digit - numStr.length()
        if diff > 0 {
            numStr = "0".repeat(diff) + numStr
        }
        return numStr
    }
}

