class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        /*
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: String, the input string containing numeric character references.
        :return: String, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'
        */
        var result = ArrayList<Rune>()
        var i = 0
        let n = string.length()
        while (i < n) {
            if (string[i] == r'&' && i + 2 < n && string[i + 1] == r'#') {
                let start = i + 2
                var is_hex = false
                var j = start
                if (j < n && string[j] == r'x') {
                    is_hex = true
                    j += 1
                }
                var num = 0
                while (j < n && (
                    (!is_hex && string[j].isDigit()) ||
                    (is_hex && NumericEntityUnescaper.is_hex_char(string[j]))
                )) {
                    j += 1
                }
                if (j > start && (j == n || string[j] == r';')) {
                    let num_str = string.substring(start + (is_hex ? 1 : 0), j - (start + (is_hex ? 1 : 0)))
                    if (!num_str.isEmpty()) {
                        let radix = is_hex ? 16 : 10
                        match (num_str.toInt(radix)) {
                            case Some(value) => 
                                result.add(value.toRune())
                                i = j + 1
                                continue
                            case None => 
                        }
                    }
                }
            }
            result.add(string[i])
            i += 1
        }
        return result.toString()
    }

    public static func is_hex_char(char: Rune): Bool {
        /*
        Determines whether a given character is a hexadecimal digit.
        :param char: Rune, the character to check.
        :return: Bool, true if the character is a hexadecimal digit, false otherwise.
        >>> NumericEntityUnescaper.is_hex_char(r'a')
        true
        */
        return char.isDigit() || 
               (char >= r'a' && char <= r'f') || 
               (char >= r'A' && char <= r'F')
    }
}

func main(): Unit {
    let unescaper = NumericEntityUnescaper()
    println(unescaper.replace("&#65;&#66;&#67;"))  // "ABC"
    println(unescaper.replace("&#x41;&#x42;&#x43;")) // "ABC" (hex version)
    println(unescaper.replace("123&#66;456")) // "123B456"
    println(unescaper.replace("&#256;")) // invalid, since 256 is out of range for valid Unicode scalar values but will parse as it's still valid number
    println(unescaper.replace("NoEntitiesHere")) // "NoEntitiesHere"
}

