        }
        return none()
    }

    public static func _validate_phoneNumber(phoneNumber: String): Option<String> {
        if (phoneNumber.length == 0 || phoneNumber.length != 11 || !phoneNumber.allMatch{ c: Char => c.isDigit() }) {
            return none()
        }
        return some(phoneNumber)
    }
