import std.collection.ArrayList
import std.sort.sort

class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..<map.size) {
                for (j in 0..<map[i].size) {
                    let char = map[i][j]
                    if (char == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (char == "G") {
                        this.targets.add(ArrayList<Int64>([i, j]))
                        this.target_count += 1
                    } else if (char == "X") {
                        this.boxes.add(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func print_map() {
        for (i in 0..<map.size) {
            for (j in 0..<map[i].size) {
                var char = map[i][j]
                var is_box = false
                for (box in boxes) {
                    if (box[0] == i && box[1] == j) {
                        char = "X"
                        is_box = true
                        break
                    }
                }
                if (!is_box) {
                    for (target in targets) {
                        if (target[0] == i && target[1] == j) {
                            char = "G"
                            break
                        }
                    }
                }
                if (i == player_row && j == player_col) {
                    char = "O"
                }
                print("${char} ")
            }
            println()
        }
    }

    public func check_win(): Bool {
        var matched_targets: Int64 = 0
        var box_copies = ArrayList<ArrayList<Int64>>()
        for (box in boxes) {
            box_copies.add(ArrayList<Int64>(box))
        }
        var target_copies = ArrayList<ArrayList<Int64>>()
        for (target in targets) {
            target_copies.add(ArrayList<Int64>(target))
        }
        sort<ArrayList<Int64>>(box_copies, by: { b1: ArrayList<Int64>, b2: ArrayList<Int64> =>
            if (b1[0] < b2[0]) {
                return Ordering.LT
            } else if (b1[0] == b2[0] && b1[1] < b2[1]) {
                return Ordering.LT
            } else if (b1[0] == b2[0] && b1[1] == b2[1]) {
                return Ordering.EQ
            } else {
                return Ordering.GT
            }
        })
        sort<ArrayList<Int64>>(target_copies, by: { t1: ArrayList<Int64>, t2: ArrayList<Int64> =>
            if (t1[0] < t2[0]) {
                return Ordering.LT
            } else if (t1[0] == t2[0] && t1[1] < t2[1]) {
                return Ordering.LT
            } else if (t1[0] == t2[0] && t1[1] == t2[1]) {
                return Ordering.EQ
            } else {
                return Ordering.GT
            }
        })
        for (i in 0..<box_copies.size) {
            if (box_copies[i][0] == target_copies[i][0] && box_copies[i][1] == target_copies[i][1]) {
                matched_targets += 1
            }
        }
        this.is_game_over = (matched_targets == target_copies.size)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_row = this.player_row
        var new_col = this.player_col
        if (direction == "w") {
            new_row -= 1
        } else if (direction == "s") {
            new_row += 1
        } else if (direction == "a") {
            new_col -= 1
        } else if (direction == "d") {
            new_col += 1
        } else {
            return false
        }

        let cell = this.map[new_row][new_col]
        if (cell == "#") {
            return false
        } else {
            var is_box = false
            var box_index = -1
            for (i in 0..<this.boxes.size) {
                let box = this.boxes[i]
                if (box[0] == new_row && box[1] == new_col) {
                    is_box = true
                    box_index = i
                    break
                }
            }
            if (is_box) {
                let next_new_row = new_row + (new_row - this.player_row)
                let next_new_col = new_col + (new_col - this.player_col)
                if (next_new_row >= 0 && next_new_row < this.map.size && 
                    next_new_col >= 0 && next_new_col < this.map[0].size) {
                    let next_cell = this.map[next_new_row][next_new_col]
                    if (next_cell == "#" || next_cell == "X" || next_cell == "G") {
                        var box_on_target = false
                        for (i in 0..<this.targets.size) {
                            let target = this.targets[i]
                            if (target[0] == new_row && target[1] == new_col) {
                                box_on_target = true
                                break
                            }
                        }
                        if (box_on_target) {
                            var next_on_target = false
                            for (target in this.targets) {
                                if (target[0] == next_new_row && target[1] == next_new_col) {
                                    next_on_target = true
                                    break
                                }
                            }
                            if (next_on_target) {
                                return false
                            } else {
                                return false
                            }
                        } else {
                            return false
                        }
                    } else {
                        for (i in 0..<this.targets.size) {
                            let target = this.targets[i]
                            if (target[0] == new_row && target[1] == new_col) {
                                this.boxes[box_index][0] = next_new_row
                                this.boxes[box_index][1] = next_new_col
                                this.player_row = new_row
                                this.player_col = new_col
                                return this.check_win()
                            }
                        }
                        this.boxes[box_index][0] = next_new_row
                        this.boxes[box_index][1] = next_new_col
                        this.player_row = new_row
                        this.player_col = new_col
                    }
                } else {
                    return false
                }
            } else {
                this.player_row = new_row
                this.player_col = new_col
            }
        }
        return this.check_win()
    }
}

