class RPGCharacter {
    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        this.name = name
        this.hp = hp
        this.attack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        let damage = this.attack_power - other_character.defense
        if damage > 0 {
            other_character.hp -= damage
        }
    }

    public func heal(): Int64 {
        let heal_amount: Int64 = 10
        let max_hp: Int64 = 100
        this.hp = if (this.hp + heal_amount) > max_hp {
            max_hp
        } else {
            this.hp + heal_amount
        }
        return this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        while amount > 0 {
            let needed_exp = this.level * 100 - this.exp
            if amount >= needed_exp {
                amount -= needed_exp
                this.exp = 0
                this.level_up()
            } else {
                this.exp += amount
                amount = 0
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        if this.level >= 100 {
            this.exp = this.level * 100
            return (this.level, this.hp, this.attack_power, this.defense)
        }
        this.level += 1
        this.hp += 20
        this.attack_power += 5
        this.defense += 5
        return (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        return this.hp > 0
    }
}

