import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        // Sentence pattern: ends with . or ? followed by space or end of string
        // Using negative lookbehind to avoid matching abbreviations like Mr.
        let pattern = Regex(#"(?<![A-Za-z])\.(?=\s)|(?<![A-Za-z])\?(?=\s|$)"#)
        let sentences = ArrayList<String>()
        var lastPos = 0

        for (md in pattern.lazyFindAll(sentences_string)) {
            let pos = md.matchPosition()
            let sentence = sentences_string.substr(start: lastPos, end: pos.start + 1) // Include punctuation
            sentences.add(sentence)
            lastPos = pos.end
        }

        // Add the last sentence if there's remaining text
        if (lastPos < sentences_string.length()) {
            sentences.add(sentences_string.substr(start: lastPos))
        }

        return sentences
    }

    public func count_words(sentence: String): Int64 {
        // Word pattern: sequences of letters only (ignoring numbers and punctuation)
        let pattern = Regex(#"[a-zA-Z]+"#)
        var count: Int64 = 0

        for (_ in pattern.lazyFindAll(sentence)) {
            count += 1
        }

        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = self.split_sentences(sentences_string: sentences_string)
        var maxCount: Int64 = 0

        for (sentence in sentences) {
            let count = self.count_words(sentence: sentence)
            if (count > maxCount) {
                maxCount = count
            }
        }

        return maxCount
    }
}

// Test cases
func main() {
    let ss = SplitSentence()

    // Test split_sentences
    let sentences1 = ss.split_sentences(sentences_string: "aaa aaaa. bb bbbb bbb? cccc cccc. dd ddd?")
    println(sentences1) // Should print ['aaa aaaa.', ' bb bbbb bbb?', ' cccc cccc.', ' dd ddd?']

    // Test count_words
    println(ss.count_words(sentence: "abc def")) // Should print 2

    // Test process_text_file
    println(ss.process_text_file(sentences_string: "aaa aaaa. bb bbbb bbb? cccc ccccccc cc ccc. dd ddd?")) // Should print 4
}

main()

