import std.string.*

class SQLGenerator {
    let table_name: String

    public init(table_name: String) {
        this.table_name = table_name
    }

    public func select(fields!: Option<ArrayList<String>> = None, condition!: Option<String> = None): String {
        let fieldStr = if (fields.isEmpty()) {
            "*"
        } else {
            let fieldsArray = fields.get()
            let fieldList = ArrayList<String>()
            for (field in fieldsArray) {
                fieldList.add(field)
            }
            fieldList.join(", ")
        }

        let conditionStr = condition.getOrElse("")
        let whereClause = if (!conditionStr.isEmpty()) {
            " WHERE " + conditionStr
        } else {
            ""
        }

        return "SELECT ${fieldStr} FROM ${this.table_name}" + whereClause + ";"
    }

    public func insert(data: HashMap<String, String>): String {
        let keys = ArrayList<String>()
        let values = ArrayList<String>()
        for (entry in data.entrySet()) {
            keys.add(entry.key)
            values.add("'" + entry.value + "'")
        }

        let keyStr = keys.join(", ")
        let valueStr = values.join(", ")

        return "INSERT INTO ${this.table_name} (${keyStr}) VALUES (${valueStr});"
    }

    public func update(data: HashMap<String, String>, condition: String): String {
        let setClauses = ArrayList<String>()
        for (entry in data.entrySet()) {
            setClauses.add("${entry.key} = '${entry.value}'")
        }

        let setStr = setClauses.join(", ")

        return "UPDATE ${this.table_name} SET ${setStr} WHERE ${condition};"
    }

    public func delete(condition: String): String {
        return "DELETE FROM ${this.table_name} WHERE ${condition};"
    }

    public func select_female_under_age(age: Int64): String {
