import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt
import std.option.Option
import std.option.Some
import std.option.None

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Option<Float64> {
        if (data.length() == 0) {
            return None
        }
        var sorted = ArrayList<Int64>(data)
        sort<Int64>(sorted, stable: true)
        let n = sorted.length()
        if (n % 2 == 1) {
            return Some(Float64(sorted[n / 2]))
        } else {
            let v1 = Float64(sorted[(n / 2) - 1])
            let v2 = Float64(sorted[n / 2])
            return Some((v1 + v2) / 2.0)
        }
    }

    public static func mode(data: ArrayList<Int64>): Option<ArrayList<Int64>> {
        if (data.length() == 0) {
            return None
        }
        var freqMap = HashMap<Int64, Int64>()
        for i in 0..<data.length() {
            let num = data[i]
            if (freqMap.containsKey(num)) {
                freqMap[num] = freqMap[num]! + 1
            } else {
                freqMap[num] = 1
            }
        }

        var maxFreq = 0
        var modes = ArrayList<Int64>()
        for kvp in freqMap {
            if (kvp.value > maxFreq) {
                maxFreq = kvp.value
                modes = ArrayList<Int64>([kvp.key])
            } else if (kvp.value == maxFreq) {
                modes.add(kvp.key)
            }
        }
        return Some(modes)
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.length() != y.length() || x.length() == 0) {
            return None
        }

        let n = Float64(x.length())
        var sumX: Float64 = 0.0
        var sumY: Float64 = 0.0
        var sumXY: Float64 = 0.0
        var sumX2: Float64 = 0.0
        var sumY2: Float64 = 0.0

        for i in 0..<x.length() {
            let xi = Float64(x[i])
            let yi = Float64(y[i])
            sumX += xi
            sumY += yi
            sumXY += xi * yi
            sumX2 += xi * xi
            sumY2 += yi * yi
        }

        let numerator = n * sumXY - sumX * sumY
        let denominator = sqrt((n * sumX2 - sumX * sumX) * (n * sumY2 - sumY * sumY))

        if (denominator == 0.0) {
            return Some(0.0)
        }
        return Some(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.length() == 0) {
            return None
        }
        var sum: Float64 = 0.0
        for i in 0..<data.length() {
            sum += Float64(data[i])
        }
        return Some(sum / Float64(data.length()))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): Option<ArrayList<ArrayList<Float64>>> {
        if (data.length() == 0) {
            return None
        }
        let n = data.length()
        for list in data {
            if (list.length() != n) {
                return None
            }
        }

        var matrix = ArrayList<ArrayList<Float64>>(capacity: n)
        for i in 0..<n {
            var row = ArrayList<Float64>(capacity: n)
            for j in 0..<n {
                if (i == j) {
                    row.add(1.0)
                } else {
                    let corr = correlation(data[i], data[j])
                    if (!corr.hasValue()) {
                        return None
                    }
                    row.add(corr.value()!)
                }
            }
            matrix.add(row)
        }
        return Some(matrix)
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let meanVal = mean(data)
        if (!meanVal.hasValue() || data.length() == 0) {
            return None
        }

        let n = Float64(data.length())
        let avg = meanVal.value()!
        var sumSquares: Float64 = 0.0

        for i in 0..<data.length() {
            let diff = Float64(data[i]) - avg
            sumSquares += diff * diff
        }

        return Some(sqrt(sumSquares / n))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let meanVal = mean(data)
        let stdVal = standard_deviation(data)
        if (!meanVal.hasValue() || !stdVal.hasValue() || stdVal.value()! == 0.0) {
            return None
        }

        let avg = meanVal.value()!
        let std = stdVal.value()!
        var zScores = ArrayList<Float64>(capacity: data.length())

        for i in 0..<data.length() {
            zScores.add((Float64(data[i]) - avg) / std)
        }

        return Some(zScores)
    }
}

