class Stock <: Equatable<Stock> {

    let name: String
    var price: Float64
    var quantity: Int64

    public init(name: String, price: Float64, quantity: Int64) {
        this.name = name
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Stock): Bool {
        return this.name != that.name || this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Stock): Bool {
        return this.name == that.name && this.price == that.price && this.quantity == that.quantity
    }
}

class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        let index = portfolio.indexOfFirst({ s => s.name == stock.name })
        if (index == -1) {
            portfolio.add(stock)
        } else {
            let existing = portfolio.get(index)
            existing.quantity += stock.quantity
            portfolio.set(index, existing)
        }
    }

    public func remove_stock(stock: Stock): Bool {
        let index = portfolio.indexOfFirst({ s => s.name == stock.name })
        if (index == -1) {
            return false
        } else {
            portfolio.remove(index)
            return true
        }
    }

    public func buy_stock(stock: Stock): Bool {
        let cost = stock.price * Float64(stock.quantity)
        if (cash_balance >= cost) {
            let index = portfolio.indexOfFirst({ s => s.name == stock.name })
            if (index == -1) {
                portfolio.add(Stock(stock.name, stock.price, stock.quantity))
            } else {
                let existing = portfolio.get(index)
                existing.quantity += stock.quantity
                portfolio.set(index, existing)
            }
            cash_balance -= cost
            return true
        } else {
            return false
        }
    }

    public func sell_stock(stock: Stock): Bool {
        let index = portfolio.indexOfFirst({ s => s.name == stock.name })
        if (index == -1) {
            return false
        } else {
            let existing = portfolio.get(index)
            if (existing.quantity >= stock.quantity) {
                let proceeds = stock.price * Float64(stock.quantity)
                if (existing.quantity == stock.quantity) {
                    portfolio.remove(index)
                } else {
                    existing.quantity -= stock.quantity
                    portfolio.set(index, existing)
                }
                cash_balance += proceeds
                return true
            } else {
                return false
            }
        }
    }

    public func calculate_portfolio_value(): Float64 {
        let total = portfol internetio.reduce(0.0, { sum, s => sum + s.price * Float64(s.quantity) })
        return cash_balance + total
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        let total_value = calculate_portfolio_value()
        let summary = ArrayList<HashMap<String, Any>>()
        for (stock in portfolio) {
            let entry = HashMap<String, Any>()
