import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let radians = x / 180.0 * PI
        let terms = 20  // Sufficient terms for reasonable accuracy
        var sum: Float64 = 0.0

        for i in 0..<terms {
            let n = 2 * i
            let term = taylor(radians, n)
            sum += term
        }

        return sum
    }

    public func factorial(a: Int64): Decimal {
        var result: Decimal = Decimal(1)
        if a == 0 {
            return result
        }

        for i in 1...a {
            result = result * Decimal.fromInt64(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        // Taylor series term for cosine: (-1)^k * x^(2k) / (2k)!
        if n % 2 != 0 {
            return 0.0  // Cosine only has even terms
        }

        let k = n / 2
        var numerator: Float64 = 1.0
        for i in 1...2*k {
            numerator *= x
        }

        let denominator = factorial(a: k).toFloat64() * factorial(a: k).toFloat64()
        let power = if k % 2 == 0 { 1.0 } else { -1.0 }

        return power * numerator / denominator
    }

    // Correct implementation using Taylor series in cos()
    // Alternative taylor implementation for cosine
    public func properCosTaylor(x: Float64, terms: Int64 = 10): Float64 {
        var result: Float64 = 0.0
        for i in 0..<terms {
            let n = 2 * i
            let numerator: Float64 = 1.0
            var x_power: Float64 = 1.0
            for j in 1...n {
                x_power *= x
            }

            let fact = factorial(a: Int64(n)).toFloat64()
            let term = (if i % 2 == 0 { 1.0 } else { -1.0 }) * x_power / fact
            result += term
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        let radians = x / 180.0 * PI
        let terms = 20
        var sum: Float64 = 0.0

        for i in 0..<terms {
            let n = 2 * i + 1
            let term = taylorForSin(x: radians, n: Int64(n))
            sum += term
        }

        return sum
    }

    public func taylorForSin(x: Float64, n: Int64): Float64 {
        // Taylor series term for sine: (-1)^k * x^(2k+1) / (2k+1)!
        if n % 2 == 0 {
            return 0.0  // Sine only has odd terms
        }

        let k = n / 2
        var numerator: Float64 = 1.0
        for i in 1...2*k+1 {
            numerator *= x
        }

        let denominator = factorial(a: Int64(2*k + 1)).toFloat64()
        let power = if k % 2 == 0 { 1.0 } else { -1.0 }

        return power * numerator / denominator
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = cos(x)
        if abs(cos_val) < 0.000001 {
            return None
        }
