import std.collection.ArrayList
import std.collection.HashMap
import std.random.Random
import std.convert.Parsable

class Parser {

    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

class TwentyFourPointGame {

    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
        this._generate_cards()
    }

    public func _generate_cards(): Unit {
        let random = Random()
        var numSet = HashSet<Int64>()
        while (numSet.size < 4) {
            let num = random.nextInt(1, 10) // Random numbers from 1 to 9
            if (!numSet.contains(num)) {
                numSet.add(num)
                this.nums.add(num)
            }
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        return this.nums.clone()
    }

    public func answer(expression: String): Bool {
        // Check that all numbers in expression are from the cards
        let tempNums = this.nums.clone()
        let tokens = ArrayList<String>()
        let sb = StringBuilder()

        for (ch in expression.toRuneArray()) {
            if (ch.isAsciiDigit()) {
                sb.append(ch.toString())
            } else {
                if (sb.size > 0) {
                    tokens.add(sb.toString())
                    sb.clear()
                }
                if (!ch.isWhitespace() && ch != r'+' && ch != r'-' && ch != r'*' && ch != r'/' && ch != r'(' && ch != r')') {
                    return false // Invalid character in expression
                }
                tokens.add(ch.toString())
            }
        }
        if (sb.size > 0) {
            tokens.add(sb.toString())
        }

        // Verify all numbers in tokens are in cards (with possible multiple digits)
        let exprNums = ArrayList<Int64>()
        var i = 0
        while (i < tokens.size) {
            let token = tokens[i]
            if (token[0].isAsciiDigit()) {
                let num = Int64.parse(token)
                if (!exprNums.contains(num)) {
                    if (!tempNums.removeFirstOccurrence(num)) {
                        return false // Number not in cards
                    }
                    exprNums.add(num)
                }
                i += 1
            } else {
                if (token[0] == r'+' || token[0] == r'-' || token[0] == r'*' || token[0] == r'/' || token[0] == r'(' || token[0] == r')') {
                    i += 1
                } else {
                    return false // Invalid token type
                }
            }
        }

        if (tempNums.size != 0 || exprNums.size != 4) {
            return false // Not all cards used or extra numbers
        }

        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        let parser = Parser(expr: expression)
        let result = parser.parse()
        return result == 24
    }
}

