import std.collection.HashMap

class URLHandler {

    /*
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    */

    let url: String

    public init(url: String) {
        /*
        Initialize URLHandler's URL
        */
        this.url = url
    }

    public func get_scheme(): Option<String> {
        /*
        get the scheme of the URL
        :return: Option<String>, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        */
        let parts = this.url.split("://")
        if parts.size() < 2 {
            return None
        }
        return Some(parts[0])
    }

    public func get_host(): Option<String> {
        /*
        Get the second part of the URL, which is the host domain name
        :return: Option<String>, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        */
        let scheme_end = this.url.indexOf("://")
        if scheme_end == -1 {
            return None
        }
        let host_start = scheme_end + 3
        let host_part = this.url.substring(host_start)
        let path_start = host_part.indexOf("/")
        if path_start != -1 {
            return Some(host_part.substring(0, path_start))
        } else {
            let query_start = host_part.indexOf("?")
            if query_start != -1 {
                return Some(host_part.substring(0, query_start))
            } else {
                let fragment_start = host_part.indexOf("#")
                if fragment_start != -1 {
                    return Some(host_part.substring(0, fragment_start))
                } else {
                    return Some(host_part)
                }
            }
        }
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let scheme_end = this.url.indexOf("://")
        if scheme_end == -1 {
            return None
        }
        let host_start = scheme_end + 3
        let host_part = this.url.substring(host_start)
        let path_start = host_part.indexOf("/")
        if path_start == -1 {
            return None
        }
        let path = host_part.substring(path_start)
        return Some(path)
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        /*
        Get the request parameters for the URL
        :return: Option<HashMap<String, String>>, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        */
        let path = this.get_path()
        if path.isNone() {
            return None
        }
        let full_path = path.get()
        let query_start = full_path.indexOf("?")
        if query_start == -1 {
            return Some(HashMap<String, String>())
        }
        let query_str = full_path.substring(query_start + 1)
        let fragment_start = query_str.indexOf("#")
        if fragment_start != -1 {
            return this.parse_query_params(query_str.substring(0, fragment_start))
        } else {
            return this.parse_query_params(query_str)
        }
    }

    private func parse_query_params(query_str: String): Option<HashMap<String, String>> {
        let params = HashMap<String, String>()
        let param_pairs = query_str.split("&")
        for pair in param_pairs {
            let kv = pair.split("=")
            if kv.size() == 2 {
                params.add(kv[0], kv[1])
            }
        }
        return Some(params)
    }

    public func get_fragment(): Option<String> {
        /*
        Get the fragment after '#' in the URL
        :return: Option<String>, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        */
        let path = this.get_path()
        if path.isNone() {
            return None
        }
        let full_path = path.get()
        let fragment_start = full_path.indexOf("#")
        if fragment_start == -1 {
            return None
        }
        return Some(full_path.substring(fragment_start + 1))
    }
}

