import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let mut dot_product = 0.0
        let mut magnitude1 = 0.0
        let mut magnitude2 = 0.0

        let size = vector_1.size()
        for i in 0..<size {
            let val1 = vector_1[i]
            let val2 = vector_2[i]
            dot_product += val1 * val2
            magnitude1 += val1 * val1
            magnitude2 += val2 * val2
        }

        magnitude1 = sqrt(magnitude1)
        magnitude2 = sqrt(magnitude2)

        if magnitude1 == 0.0 || magnitude2 == 0.0 {
            return 0.0
        }

        return dot_product / (magnitude1 * magnitude2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let mut similarities = ArrayList<Float64>()
        let size = vector_1.size()
        let mut magnitude1 = 0.0
        for i in 0..<size {
            magnitude1 += vector_1[i] * vector_1[i]
        }
        magnitude1 = sqrt(magnitude1)
        if magnitude1 == 0.0 {
            for _ in 0..<vectors_all.size() {
                similarities.add(0.0)
            }
            return similarities
        }

        for i in 0..<vectors_all.size() {
            let vector_2 = vectors_all[i]
            let mut dot_product = 0.0
            let mut magnitude2 = 0.0
            for j in 0..<size {
                dot_product += vector_1[j] * vector_2[j]
                magnitude2 += vector_2[j] * vector_2[j]
            }
            magnitude2 = sqrt(magnitude2)
            let similarity = if magnitude2 == 0.0 {
                0.0
            } else {
                dot_product / (magnitude1 * magnitude2)
            }
            similarities.add(similarity)
        }
        return similarities
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let mut magnitude1 = 0.0
        let mut magnitude2 = 0.0
        let mut dot_product = 0.0

        for i in 0..<vector_list_1.size() {
            let vec1 = vector_list_1[i]
            for j in 0..<vec1.size() {
                magnitude1 += vec1[j] * vec1[j]
            }
        }
        magnitude1 = sqrt(magnitude1)

        for i in 0..<vector_list_2.size() {
            let vec2 = vector_list_2[i]
            for j in 0..<vec2.size() {
                magnitude2 += vec2[j] * vec2[j]
            }
        }
        magnitude2 = sqrt(magnitude2)

        for i in 0..<vector_list_1.size() {
            let vec1 = vector_list_1[i]
            for j in 0..<vector_list_2.size() {
                let vec2 = vector_list_2[j]
                for k in 0..<vec1.size() {
                    if k < vec2.size() {
                        dot_product += vec1[k] * vec2[k]
                    }
                }
            }
        }

        if magnitude1 == 0.0 || magnitude2 == 0.0 {
            return 0.0
        }

        return dot_product / (magnitude1 * magnitude2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let mut weight_dict = HashMap<String, Float64>()
        for entry in number_dict {
            let (key, value) = entry
            let idf = log((total_num + 1.0) / (value + 1.0))
            weight_dict.put(key, idf)
        }
        return weight_dict
    }
}

