import std.collection.HashMap
import std.collection.ArrayList

class Product <: Equatable<Product> {

    let price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Product): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Product): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class VendingMachine {

    var inventory: HashMap<String, Product>
    var balance: Float64

    public init() {
        this.inventory = HashMap<String, Product>()
        this.balance = 0.0
    }

    public func add_item(item_name: String, price: Float64, quantity: Int64): Unit {
        let product = Product(price, quantity)
        println("Adding item: ${item_name}, price: ${price}, quantity: ${quantity}")
        if (inventory.contains(item_name)) {
            let old_product = inventory.get(item_name).getOrThrow()
            let new_product = Product(price, old_product.quantity + quantity)
            inventory.set(item_name, new_product)
            println("Updated existing item quantity")
        } else {
            inventory.set(item_name, product)
            println("Added new item")
        }
    }

    public func insert_coin(amount: Float64): Float64 {
        println("Inserting coin: ${amount}")
        this.balance += amount
        println("Current balance: ${this.balance}")
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        println("Attempting to purchase: ${item_name}")
        match (inventory.get(item_name)) {
            case Some(product) => {
                if (product.quantity > 0) {
                    if (this.balance >= product.price) {
                        this.balance -= product.price
                        let new_product = Product(product.price, product.quantity - 1)
                        inventory.set(item_name, new_product)
                        println("Purchase successful. Remaining balance: ${this.balance}")
                        return Some(this.balance)
                    } else {
                        println("Insufficient balance")
                        return None
                    }
                } else {
                    println("Item out of stock")
                    return None
                }
            }
            case None => {
                println("Item not found")
                return None
            }
        }
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        println("Restocking item: ${item_name}, quantity: ${quantity}")
        match (inventory.get(item_name)) {
            case Some(product) => {
                let new_product = Product(product.price, product.quantity + quantity)
                inventory.set(item_name, new_product)
                println("Restocked item successfully")
                return true
            }
            case None => {
                println("Item not found in inventory")
                return false
            }
        }
    }

    public func display_items(): Option<String> {
        println("Displaying items...")
        if (inventory.isEmpty()) {
            println("Inventory is empty")
            return None
        } else {
            let mut items_list = ArrayList<String>()
            for ((item_name, product) in inventory.entries()) {
                let item_str = "${item_name} - $${product.price} [${product.quantity}]"
                items_list.add(item_str)
            }
            let result = items_list.joinToString(", ")
            println(result)
            return Some(result)
        }
    }
}

