import std.collection.HashMap
import std.math.abs

class Weather {

    let weather: String
    let temperature: Float64
    let temperature_units: String

    public init(weather: String, temperature: Float64, temperature_units: String) {
        this.weather = weather
        this.temperature = temperature
        this.temperature_units = temperature_units
    }
}

class WeatherSystem {

    var temperature: Float64
    var weather: String
    var city: String
    var weather_list: HashMap<String, Weather>

    public init(city: String) {
        this.temperature = Float64.NaN
        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = "celsius"): Option<(Float64, String)> {
        match (weather_list.get(this.city)) {
            case Some(w) => 
                var result_temp: Float64 = w.temperature
                match (tmp_units) {
                    case "fahrenheit" =>
                        if (w.temperature_units == "celsius") {
                            result_temp = this.celsius_to_fahrenheit_value(w.temperature)
                        }
                    case "celsius" =>
                        if (w.temperature_units == "fahrenheit") {
                            result_temp = this.fahrenheit_to_celsius_value(w.temperature)
                        }
                    case _ => 
                        println("Unknown temperature unit, returning original value")
                }
                Some((result_temp, w.weather))
            case None => None
        }
    }

    private func celsius_to_fahrenheit_value(c: Float64): Float64 {
        return c * 9.0 / 5.0 + 32.0
    }

    private func fahrenheit_to_celsius_value(f: Float64): Float64 {
        return (f - 32.0) * 5.0 / 9.0
    }

    public func set_city(city: String): Unit {
        this.city = city
    }

    public func celsius_to_fahrenheit(): Float64 {
        match (this.weather_list.get(this.city)) {
            case Some(w) =>
                if (w.temperature_units == "celsius") {
                    return this.celsius_to_fahrenheit_value(w.temperature)
                } else {
                    println("Temperature is not in celsius,conversion not performed")
                    return Float64.NaN
                }
            case None =>
                println("No weather data for this city")
                return Float64.NaN
        }
    }

    public func fahrenheit_to_celsius(): Float64 {
        match (this.weather_list.get(this.city)) {
            case Some(w) =>
                if (w.temperature_units == "fahrenheit") {
                    return this.fahrenheit_to_celsius_value(w.temperature)
                } else {
                    println("Temperature is not in fahrenheit,conversion not performed")
                    return Float64.NaN
                }
            case None =>
                println("No weather data for this city")
                return Float64.NaN
        }
    }
}

main() {
    let weatherSystem = WeatherSystem("New York")
    let mut weather_list = HashMap<String, Weather>()
    weather_list.add("New York", Weather("sunny", 27.0, "celsius"))
    weather_list.add("Beijing", Weather("cloudy", 23.0, "celsius"))

    // Test query method
    match (weatherSystem.query(weather_list)) {
        case Some((temp, weather)) =>
            println("Temperature: ${temp}, Weather: ${weather}")
        case None =>
            println("No weather data found for city")
    }

    // Test query with fahrenheit conversion
    match (weatherSystem.query(weather_list, "fahrenheit")) {
        case Some((temp, weather)) =>
            println("Temperature(F): ${temp}, Weather: ${weather}")
        case None =>
            println("No weather data found for city")
    }

    // Test set_city
    weatherSystem.set_city("Beijing")
    match (weatherSystem.query(weather_list)) {
        case Some((temp, weather)) =>
            println("Temperature(Beijing): ${temp}, Weather: ${weather}")
        case None =>
            println("No weather data found for Beijing")
    }

    // Test celsius_to_fahrenheit
    weatherSystem.weather_list.add("New York", Weather("sunny", 27.0, "celsius"))
    let f_temp = weatherSystem.celsius_to_fahrenheit()
    if (!f_temp.isNaN) {
        println("27°C to Fahrenheit: ${f_temp}")
    }

    // Test fahrenheit_to_celsius
    weatherSystem.weather_list.add("Test", Weather("sunny", 80.6, "fahrenheit"))
    weatherSystem.set_city("Test")
    let c_temp = weatherSystem.fahrenheit_to_celsius()
    if (!c_temp.isNaN) {
        println("80.6°F to Celsius: ${c_temp}")
    }
}

