import std.collection.HashMap
import std.collection.ArrayList
import std.regex.*

class Words2Numbers {

    /*
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    */

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        /*
        Initialize the word lists and dictionaries required for conversion
        */
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = (1, 0)
        for (idx in 0..this.units.size) {
            this.numwords[this.units[idx]] = (1, idx.toLong())
        }
        for (idx in 0..this.tens.size) {
            this.numwords[this.tens[idx]] = (1, (idx * 10).toLong())
        }
        for (idx in 0..this.scales.size) {
            if (idx * 3 == 0) {
                this.numwords[this.scales[idx]] = (100, 0)
            } else {
                this.numwords[this.scales[idx]] = ((Int64(10) ** (idx * 3)), 0)
            }
        }

        this.ordinal_words = HashMap<String, Int64>([("first", 1), ("second", 2), ("third", 3), ("fifth", 5), ("eighth", 8), ("ninth", 9), ("twelfth", 12)])
        this.ordinal_endings = ArrayList<(String, String)>([("ieth", "y"), ("th", "")])
    }

    public func text2int(textnum: String): Option<String> {
        /*
        Convert the word string to the corresponding integer string
        :param textnum: String, the word string to be converted
        :return: Option<String>, the converted integer string or None if conversion fails
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two").match { v => println(v); return true } null
        Some("32")
        */
        let parts = textnum.toLowerCase().split(#/[^a-zA-Z-]+/#).filter({s => s.length > 0 && s != "-"})
        if (parts.isEmpty()) {
            return None
        }

        var current: Int64 = 0
        var result: Int64 = 0

        for (word in parts) {
            let processedWord = word.split("-").joinWith("")
            if (processedWord == "and") {
                continue
            }

            let found = this.numwords.get(processedWord)
            if (found.isNone()) {
                // Check for ordinal words not in main map
                let ordinalNum = this.ordinal_words.get(processedWord)
                if (ordinalNum.isSome()) {
                    current += ordinalNum.unwrap()
                    continue
                }

                // Check if word ends with ordinal endings
                var matched = false
                for ((ending, replacement) in this.ordinal_endings) {
                    if (processedWord.endsWith(ending)) {
                        let baseWord = processedWord[0..processedWord.length - ending.length] + replacement
                        let baseNum = this.numwords.get(baseWord)
                        if (baseNum.isSome()) {
                            let (scale, value) = baseNum.unwrap()
                            current += value
                            matched = true
                            break
                        }
                    }
                }
                if (matched) {
                    continue
                }

                // Handle hyphenated numbers like "twenty-one"
                if (word.contains("-")) {
                    let subWords = word.split("-")
                    var hyphenTotal: Int64 = 0
                    var valid = true
                    for (subWord in subWords) {
                        let subRes = this.numwords.get(subWord.toLowerCase())
                        if (subRes.isNone()) {
                            valid = false
                            break
                        }
                        let (scale, value) = subRes.unwrap()
                        hyphenTotal += value
                    }
                    if (valid) {
                        current += hyphenTotal
                        continue
                    }
                }

                return None
            }

            let (scale, value) = found.unwrap()
            current = current * scale + value

            // Handle scale words (thousand, million, etc.)
            if (scale > 100) {
                result += current
                current = 0
            }
        }

        result += current
        return Some(result.toString())
    }

    public func is_valid_input(textnum: String): Bool {
        /*
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: true if input is valid, false otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        true
        */
        let parts = textnum.toLowerCase().split(#/[^a-zA-Z-]+/#).filter({s => s.length > 0 && s != "-"})
        if (parts.isEmpty()) {
            return false
        }

        for (word in parts) {
            let processedWord = word.split("-").joinWith("")
            if (processedWord == "and") {
                continue
            }

            if (this.numwords.containsKey(processedWord)) {
                continue
            }

            // Check for ordinal words
            if (this.ordinal_words.containsKey(processedWord)) {
                continue
            }

            // Check ordinal endings
            var matched = false
            for ((ending, _) in this.ordinal_endings) {
                if (processedWord.endsWith(ending)) {
                    let baseWord = processedWord[0..processedWord.length - ending.length]
                    if (this.numwords.containsKey(baseWord)) {
                        matched = true
                        break
                    }
                }
            }
            if (matched) {
                continue
            }

            // Handle hyphenated numbers
            if (word.contains("-")) {
                let subWords = word.split("-")
                var valid = true
                for (subWord in subWords) {
                    if (!this.numwords.containsKey(subWord.toLowerCase())) {
                        valid = false
                        break
                    }
                }
                if (valid) {
                    continue
                }
            }

            return false
        }

        return true
    }
}

// Test cases
main() {
    let w2n = Words2Numbers()

    // Test is_valid_input
